// CSD_RATIONALE_BEGIN
// Attempt 71: primary failure analysis across attempts 40–70 shows that
// RegenerateUnitOnGroundingFailure's grounding checks never trigger on the
// observed wrong-answer examples — the model always picks real schema tokens
// (MAX(flightno), paragraph_id, etc.) which pass grounding. The grounding
// helper therefore adds overhead (retries, rollbacks) with no measurable benefit
// on Spider mode_A failures.
//
// This attempt replaces Phase 3 (RegenerateUnitOnGroundingFailure) with
// ConstrainedGeneration, which is a clean hard-parser loop that terminates as
// soon as the parser reaches completeness, EOS, or the budget. Benefits:
// - Removes grounding-retry overhead, freeing wall-clock budget per example.
// - Terminates as soon as the parser accepts a complete parse, preventing
//   budget runaway on short queries.
// - Preserves all structural correctness properties (parser validity,
//   step accounting, span management).
//
// All other phases unchanged from best attempt (66 / "best result so far"):
// Phase 1: ≤5 unconstrained preamble steps for "SQL: <<".
// Phase 2: OpenConstrainedSpan if not already inside.
// Phase 3: ConstrainedGeneration(budget=min(remaining-1, 300)).
// Phase 4: CloseConstrainedSpan if complete, else CloseSpanWithinBudget(120).
// Guidance: identical to best attempt 66 (no anti-alias clauses that caused
// the attempt-65 regression).
//
// Budget ceiling: Phase1(5)+Phase2(1)+Phase3(300)+Phase4(120) = 426 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the
//   implication is vacuous on every iteration. When RenderedEndsWith fires,
//   currentConstrainedOut := [] and IsValidPrefix([]) holds by the method
//   precondition. EOS break leaves insideConstrainedOut false (vacuous).
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by the method precondition.
//
// Phase 3 ConstrainedGeneration: The helper loops ConstrainedStep, which
//   hard-masks to parser-valid next tokens at every step. Its postcondition
//   guarantees parser.IsValidPrefix(resultConstrained). We assign
//   currentConstrainedOut := resultConstrained, re-establishing the invariant.
//   insideConstrainedOut remains true (unchanged in Phase 3).
//
// Phase 4a CloseConstrainedSpan: Requires parser.IsCompletePrefix (which
//   implies IsValidPrefix). Sets insideConstrainedOut := false, making the
//   implication vacuously true; clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step; appends 0 (EOS) or 1 (non-EOS)
//   token per iteration. Invariant preserved each iteration (1 step, ≤1 token).
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<" token.
//   Ratio 1:1.
//
// Phase 3: ConstrainedGeneration postcondition: cost = |resultConstrained|
//   + (terminatedByEos ? 1 : 0) <= sqlBudget. We set steps += sqlBudget
//   (upper bound). |generated_new| = |generated_old| + |resultConstrained|
//   <= |generated_old| + sqlBudget <= |generatedPrefix| + old_steps + sqlBudget
//   = |generatedPrefix| + new_steps. ✓
//   Also |currentConstrainedOut| = |resultConstrained| <= |generated_new|. ✓
//
// Phase 4a: CloseConstrainedSpan costs 1 step, appends at most 1 ">>" token.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved transitively.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained SQL generation via ConstrainedGeneration.
// Budget capped at 300 to prevent runaway repetition loops while covering
// the full Spider query distribution (median ~26 tokens, max ~80 for complex).
// ConstrainedGeneration terminates as soon as parser reaches completeness,
// eliminating grounding-check overhead that never triggers on Spider mode_A.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 300 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 300;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained, terminatedByEos := helpers.ConstrainedGeneration(lm, parser, constrainedPrompt, sqlBudget, eosToken);
    generated := generated + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

